import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { useAuthStore } from "@/stores/authStore";
import { createRunPolicyClient, RunPolicyReadbackUnavailable } from "../runPolicy";
import { runScopeSchema } from "../runPolicyTransport";
import fixture from "./runPolicy.core-fixture.json";

// Generated by support/r29-core-contract.py via the real existing Flask/owner
// fixtures with synthetic data only. No hand-written success envelopes here.
beforeEach(() => useAuthStore.setState(s => ({ status: "logged-in", username: "synthetic", token: "synthetic-core-contract", sessionGeneration: s.sessionGeneration + 1 })));
afterEach(() => vi.unstubAllGlobals());
it.each(fixture.map((record, index) => ({ record, index, action: record.proposal.action })))("consumes real core HTTP configuration case $index ($action)", async ({ record }) => {
  const scope = runScopeSchema.parse(record.before.scope);
  const path = `/ft-api/v1/model-runs/${scope.run_id}/configuration`;
  const exactPath = record.proposal.action === "learning-rights" ? `${path}/control?action=learning-rights&subject=${record.proposal.value.subject}` : path;
  const calls: string[] = [];
  let reads = 0;
  vi.stubGlobal("fetch", vi.fn(async (url: string, init?: RequestInit) => {
    calls.push(`${init?.method} ${url}`);
    if (url === path && init?.method === "GET") return new Response(JSON.stringify(reads++ ? record.after : record.before));
    if (url === exactPath && init?.method === "GET") return new Response(JSON.stringify(record.after)); // preserved legacy missing-control negative
    if (url === `${path}/preview` && init?.method === "POST") {
      expect(JSON.parse(String(init.body))).toEqual(record.proposal);
      return new Response(JSON.stringify(record.preview));
    }
    expect(url).toBe(`${path}/confirm`); expect(init?.method).toBe("POST");
    expect(JSON.parse(String(init?.body))).toEqual({ ...record.proposal, confirmation: record.preview.confirmation });
    return new Response(JSON.stringify(record.confirmed));
  }));
  const client = createRunPolicyClient(scope);
  await expect(client.read()).resolves.toEqual(record.before);
  const preview = await client.preview(record.proposal);
  if (record.proposal.action === "learning-rights") {
    await expect(client.confirm(preview)).rejects.toBeInstanceOf(RunPolicyReadbackUnavailable);
  } else await expect(client.confirm(preview)).resolves.toEqual(record.after);
  expect(calls).toEqual([`GET ${path}`, `POST ${path}/preview`, `POST ${path}/confirm`, `GET ${exactPath}`]);
  await expect(client.confirm(preview)).rejects.toThrow(/consumed/);
  expect(calls).toHaveLength(4);
});
